import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"LocalSend 區域網路傳輸設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/localsend.md","filePath":"zh-HK/user-guide/settings/localsend.md","lastUpdated":1787586465000}'),n={name:"zh-HK/user-guide/settings/localsend.md"};function l(s,o,i,d,c,g){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="localsend-區域網路傳輸設定" tabindex="-1">LocalSend 區域網路傳輸設定 <a class="header-anchor" href="#localsend-區域網路傳輸設定" aria-label="Permalink to &quot;LocalSend 區域網路傳輸設定&quot;">​</a></h1><p>Lertaro 內建了與官方開源 <a href="https://localsend.org" target="_blank" rel="noreferrer">LocalSend</a> 協定原生相容的區域網路無線傳輸引擎。無需依賴外部網際網路或傳輸線，即可在同一區域網路下的 Windows 電腦、Mac、Linux、iPhone、iPad 以及 Android 手機之間極速互傳檔案、資料夾與純文字。設定頁面路徑為<strong>設定 → LocalSend</strong>。</p><h2 id="_1-基礎服務設定" tabindex="-1">1. 基礎服務設定 <a class="header-anchor" href="#_1-基礎服務設定" aria-label="Permalink to &quot;1. 基礎服務設定&quot;">​</a></h2><ul><li><strong>啟用 LocalSend 區域網路傳輸</strong>：總開關。開啟後，Lertaro 會在後台啟動輕量級傳輸監聽服務，並在系統匣選單中啟用「傳送到其他裝置...」功能項目。</li><li><strong>裝置名稱</strong>：本機在區域網路多播廣播中向其他裝置展示的別名。預設根據電腦名稱自動產生，你可以隨時修改為一個更具辨識度的名稱（例如 <code>工作筆記型電腦</code>）。</li><li><strong>服務連接埠</strong>：HTTP / HTTPS 傳輸監聽連接埠（遵循 LocalSend 官方標準，預設為 <code>53317</code>）。若本機該連接埠被其他服務占用，可在此自訂更改。</li></ul><h2 id="_2-安全加密與儲存規則" tabindex="-1">2. 安全加密與儲存規則 <a class="header-anchor" href="#_2-安全加密與儲存規則" aria-label="Permalink to &quot;2. 安全加密與儲存規則&quot;">​</a></h2><ul><li><strong>加密傳輸 (HTTPS)</strong>：預設開啟。啟用後裝置間的資料往來均採用 TLS 加密傳輸，防止區域網路封包窺探。</li><li><strong>接收 PIN 碼</strong>：可設定 4–6 位數 PIN 碼。設定後，其他裝置向你發起傳輸請求時必須在發送端輸入相符的 PIN 碼方可建立連線（留空則不開啟驗證）。</li><li><strong>自動儲存檔案</strong>：開啟後，接收來自區域網路裝置的傳輸請求將自動確認並下載儲存，無需每次手動按一下彈出視窗確認。</li><li><strong>儲存目錄</strong>：設定接收到的檔案與資料夾預設儲存的實體目標路徑（預設儲存在用戶系統的 <code>Downloads\\LocalSend</code> 目錄下），按一下右側瀏覽按鈕可隨時更改。</li></ul><h2 id="_3-發送視窗與快捷調用" tabindex="-1">3. 發送視窗與快捷調用 <a class="header-anchor" href="#_3-發送視窗與快捷調用" aria-label="Permalink to &quot;3. 發送視窗與快捷調用&quot;">​</a></h2><ul><li><strong>快捷鍵喚起</strong>：可在全域任何介面按下預設快捷鍵 <strong><code>Ctrl+S</code></strong>（可在<a href="./hotkeys-page.html"><strong>設定 → 熱鍵</strong></a>中重新綁定）瞬間喚起 LocalSend 獨立發送視窗。</li><li><strong>發送模式切換</strong>：發送視窗頂部支援在 <strong>[發送檔案 / 資料夾]</strong> 與 <strong>[發送文字]</strong> 兩種模式之間一鍵切換。</li><li><strong>即時拖曳分發</strong>：支援直接從 Lertaro 搜尋結果列表、快速面板或檔案總管中將多個檔案或整個專案目錄拖入發送視窗，雷達掃描會自動列出區域網路內當前線上的所有裝置，按一下目標裝置頭像即可全速發送。</li></ul>',8)])])}const u=e(n,[["render",l]]);export{_ as __pageData,u as default};
